{
	@param var animationMatrix:Mat4;
	@global var global:{ @perObject
	var modelView : Mat4};
	@input var input:{ var normal : Vec3};
	var relativePosition:Vec3;
	var transformedNormal:Vec3;
	function vertex() {
		relativePosition = relativePosition * animationMatrix.mat3x4();
		transformedNormal = (input.normal * animationMatrix.mat3() * global.modelView.mat3()).normalize();
	};
}

begin.haxe_doc:
Starts emitting instances: removes the previous instances and prepares the buffers.
		Call it, then for each instance set the batch transform (or `worldPosition`) and the shader parameters,
		and call `emitInstance`.

		```haxe
		batch.begin(units.length);
		for( u in units ) {
			batch.setPosition(u.x, u.y, 0);
			colorShader.color.setColor(u.color);
			batch.emitInstance();
		}
		```
		@param emitCountTip The expected number of instances, used to size the buffers (128 by default).
		@return The number of instances the buffers were sized for.

new.haxe_doc:
Creates a mesh batch drawing instances of `primitive`. The batch does not support colliders.
		@param primitive The primitive drawn by each instance.
		@param material The material, or `null` for a default one.
		@param parent An optional parent object.

Creates the batches from `object`, which becomes a hidden child used as animation source.
		@param object The object to copy. Play animations on the batcher with `playAnimation`.
		@param spawn Called repeatedly to place the copies: it must fill the given matrix with the world transform of the
		next copy and return `true`, or return `false` when there are no more copies.
		@param parent An optional parent object.

Creates an empty library.
		@param isDynamic If `true`, models can be added after the first upload.
		@param maxUploadSize The maximum number of bytes uploaded per frame, or `-1` for no limit.

addInstance.haxe_doc:
Registers the meshes of `obj` (their primitives must be `h3d.prim.HMDModel` or `h3d.prim.Polygon`) and returns a
		model which can be emitted with `emitInstance`. `obj` itself is not modified and does not need to be in the scene.
		@param recChildren If `true`, also registers the meshes of all its descendants.

emitInstance.haxe_doc:
Adds an instance of a model registered with `addInstance`.
		@param worldPosition The transform of the instance (relative to the batcher if `isRelative` is set).
		@param syncID A value stored per instance, read by the `syncShader`.
		@param groupID The group of the instance: prefer `BatchGroup.emitInstance`.

new.haxe_doc:
Creates a batcher.
		@param parent The parent object.
		@param renderer The renderer of the scene, used to set up the material passes.
		@param library The geometry library, or `null` to create one owned by this batcher.
		@param batchFlags The options of the batcher.

m.e:
{
	@param var instancesData:RWBuffer<Vec4>;
	@param var instanceStride:Int;
	@param var modelViewOffset:Int;
	@param var instanceCount:Int;
	@param var syncIDs:StorageBuffer<Int>;
	function getModelView(id:Int):Mat4 {
		var modelViewPos = id * instanceStride + modelViewOffset;
		return mat4(instancesData[modelViewPos + 0], instancesData[modelViewPos + 1], instancesData[modelViewPos + 2], instancesData[modelViewPos + 3]);
	};
	function fillModelView(id:Int, modelView:Mat4) {
		var modelViewPos = id * instanceStride + modelViewOffset;
		instancesData[modelViewPos + 0] = modelView[0];
		instancesData[modelViewPos + 1] = modelView[1];
		instancesData[modelViewPos + 2] = modelView[2];
		instancesData[modelViewPos + 3] = modelView[3];
	};
}

{
	@const var ENABLE_FRUSTUM_CULLING:Bool;
	@const var ENABLE_DISTANCE_CLIPPING:Bool;
	@const var ENABLE_DIRLIGHT_OBB_CULLING:Bool;
	@const var ENABLE_HZB_CULLING:Bool;
	@global var camera:{ var position : Vec3; var proj : Mat4; var view : Mat4; var zNear : Float; var zFar : Float};
	@param var instancesData:StorageBuffer<Vec4>;
	@param var instanceStride:Int;
	@param var modelViewOffset:Int;
	@param var instancesInfos:StorageBuffer<Int>;
	@param var subMeshInfos:StorageBuffer<Vec4>;
	@param var lodInfos:StorageBuffer<Float>;
	@param var subPartInfos:StorageBuffer<Int>;
	@param var countBuffer:RWBuffer<Int>;
	@param var commandBuffer:RWBuffer<Int>;
	@param var instanceCount:Int;
	@const var IS_RELATIVE:Bool;
	@param var worldMatrix:Mat4;
	@param var frustum:Buffer<Vec4,6>;
	@param var maxDistance:Float = -1;
	@param var meshLodScale:Float = 1.0;
	var subMeshInfosStride:Int = 2;
	var subPartInfosStride:Int = 2;
	@param var lightMatrix:Mat3;
	@param var lightOBBMin:Vec3;
	@param var lightOBBMax:Vec3;
	@param var hzb:Sampler2D;
	@param var hzbSize:Vec2;
	function insideOBB(pos:Vec3, radius:Float, min:Vec3, max:Vec3):Bool {
		return (pos.x + radius) > min.x && (pos.x - radius) < max.x && (pos.y + radius) > min.y && (pos.y - radius) < max.y && (pos.z + radius) > min.z && (pos.z - radius) < max.z;
	};
	function emitInstance(instanceID:Int, indexCount:Int, instanceCount:Int, startIndex:Int, startVertex:Int, baseInstance:Int) {
		var instancePos = instanceID * 5;
		commandBuffer[instancePos + 0] = indexCount;
		commandBuffer[instancePos + 1] = instanceCount;
		commandBuffer[instancePos + 2] = startIndex;
		commandBuffer[instancePos + 3] = startVertex;
		commandBuffer[instancePos + 4] = baseInstance;
	};
	function computeScreenRatio(distToCam:Float, radius:Float):Float {
		var screenMultiple = max(0.5 * camera.proj[0][0], 0.5 * camera.proj[1][1]);
		var screenRadius = screenMultiple * radius / max(1.0, distToCam);
		return 2.0 * screenRadius * meshLodScale;
	};
	function main() {
		setLayout(64, 1, 1);
		var instanceID = computeVar.workGroup.x * 64 + computeVar.localInvocationIndex;
		if (instanceID >= instanceCount) return;
		var modelViewPos = instanceID * instanceStride + modelViewOffset;
		var modelView = mat4(instancesData[modelViewPos + 0], instancesData[modelViewPos + 1], instancesData[modelViewPos + 2], instancesData[modelViewPos + 3]);
		var scale = vec3(length(vec3(modelView[0].x, modelView[1].x, modelView[2].x)), length(vec3(modelView[0].y, modelView[1].y, modelView[2].y)), length(vec3(modelView[0].z, modelView[1].z, modelView[2].z)));
		if (dot(scale, scale) < 1e-12) return;
		var flags:Int = instancesInfos[instanceID];
		var subMeshID:Int = flags >> 16;
		var subMeshPos = subMeshID * subMeshInfosStride;
		var localSphere = subMeshInfos[subMeshPos + 0];
		var lodInfo = subMeshInfos[subMeshPos + 1];
		var lodStart:Int = floatBitsToInt(lodInfo.x);
		var lodCount:Int = floatBitsToInt(lodInfo.y);
		var localCenter = vec4(localSphere.xyz, 1.0);
		var position = vec3(dot(modelView[0], localCenter), dot(modelView[1], localCenter), dot(modelView[2], localCenter));
		if (IS_RELATIVE) {
			position = position * worldMatrix.mat3x4();
			var worldScale = vec3(length(vec3(worldMatrix[0].x, worldMatrix[1].x, worldMatrix[2].x)), length(vec3(worldMatrix[0].y, worldMatrix[1].y, worldMatrix[2].y)), length(vec3(worldMatrix[0].z, worldMatrix[1].z, worldMatrix[2].z)));
			scale *= worldScale;
		};
		var boundingSphere = localSphere.w * max(scale.x, max(scale.y, scale.z));
		if (ENABLE_FRUSTUM_CULLING) {
			@unroll for (i  in  0 ... 6) {
				var plane = frustum[i];
				if ((dot(plane.xyz, position) - plane.w) < -boundingSphere) return;
			};
		};
		if (ENABLE_DIRLIGHT_OBB_CULLING) {
			var objPosLs = position * lightMatrix;
			if (!insideOBB(objPosLs, boundingSphere, lightOBBMin, lightOBBMax)) return;
		};
		if (ENABLE_HZB_CULLING) {
			var posView = vec4(position, 1.0) * camera.view;
			var depthView = posView.z - boundingSphere;
			var objDepthMin = (camera.zFar * (depthView - camera.zNear)) / (depthView * (camera.zFar - camera.zNear));
			var aabbCornersViewSpace = [posView.xyz + vec3(boundingSphere, boundingSphere, -boundingSphere), posView.xyz + vec3(boundingSphere, -boundingSphere, -boundingSphere), posView.xyz + vec3(-boundingSphere, boundingSphere, -boundingSphere), posView.xyz + vec3(-boundingSphere, -boundingSphere, -boundingSphere)];
			var offscreen = false;
			var aabbCornersUVSpace = [vec2(0), vec2(0), vec2(0), vec2(0)];
			var aabbMinMax = [1e30, -1e30, 1e30, -1e30];
			@unroll for (i  in  0 ... 4) {
				var cornerViewSpace = aabbCornersViewSpace[i];
				var cornerScreenPos = vec4(cornerViewSpace, 1.0) * camera.proj;
				cornerScreenPos.xyz /= cornerScreenPos.w;
				cornerScreenPos.xy = screenToUv(cornerScreenPos.xy);
				aabbCornersUVSpace[i] = cornerScreenPos.xy;
				aabbMinMax[0] = min(aabbMinMax[0], aabbCornersUVSpace[i].x);
				aabbMinMax[1] = max(aabbMinMax[1], aabbCornersUVSpace[i].x);
				aabbMinMax[2] = min(aabbMinMax[2], aabbCornersUVSpace[i].y);
				aabbMinMax[3] = max(aabbMinMax[3], aabbCornersUVSpace[i].y);
				if (aabbCornersUVSpace[i].x <= 0.0 || aabbCornersUVSpace[i].x >= 1.0 || aabbCornersUVSpace[i].y <= 0.0 || aabbCornersUVSpace[i].y >= 1.0) offscreen = true;
			};
			var boxWidth = aabbMinMax[1] - aabbMinMax[0];
			var boxHeight = aabbMinMax[3] - aabbMinMax[2];
			var texelSize = vec2(boxWidth, boxHeight) * hzbSize;
			var w = max(texelSize.x, texelSize.y);
			var mip = max(0.0, ceil(log2(w))) + 1;
			mip = clamp(mip, 0.0, log2(max(hzbSize.x, hzbSize.y)));
			var mipSize = max(vec2(1.0), floor(hzbSize / pow(vec2(2.0), vec2(mip))));
			var depth = 0.0;
			@unroll for (i  in  0 ... 4) {
				var cornerPos = ivec2(clamp(aabbCornersUVSpace[i] * mipSize, vec2(0.0), mipSize - vec2(1.0)));
				var cornerDepth = hzb.fetchLod(cornerPos, int(mip)).x;
				depth = max(depth, cornerDepth);
			};
			if (!offscreen && objDepthMin > depth) return;
		};
		var toCam = camera.position - position.xyz;
		var distToCam = length(toCam);
		if (ENABLE_DISTANCE_CLIPPING) if (distToCam > maxDistance) return;
		var screenRatio = computeScreenRatio(distToCam, boundingSphere);
		var lodSelected:Int = 0;
		for (i  in  0 ... lodCount) {
			var minScreenRatio = lodInfos[lodStart + i];
			if (screenRatio > minScreenRatio) break;
			lodSelected++;
		};
		if (lodSelected >= lodCount) return;
		var subPartID:Int = flags & 0xFFFF;
		var subPartPos = (subPartID + lodSelected) * subPartInfosStride;
		var indexCount:Int = subPartInfos[subPartPos + 0];
		var indexStart:Int = subPartInfos[subPartPos + 1];
		var id = atomicAdd(countBuffer, 0, 1);
		emitInstance(id, indexCount, 1, indexStart, 0, instanceID);
	};
}

lineStyle.haxe_doc:
Sets the style of the next lines.
		@param size The line width: in pixels, or in world units when `is3D` is set. `0` keeps the current width.
		@param color The line color, in `0xRRGGBB` format.
		@param alpha The line opacity, from `0` to `1`.

setColor.haxe_doc:
Sets the color of the next lines.
		@param color The color, in `0xRRGGBB` format.
		@param alpha The opacity, from `0` to `1`.

class.haxe_doc:
Draws 3D lines with an API similar to `h2d.Graphics`: set a style with `lineStyle`, then `moveTo` / `lineTo`.
	Mostly used for debug display (see `Box`, `Sphere` and `Capsule`).

	By default lines are drawn in screen space: their width is in pixels whatever the distance.
	With `is3D`, consecutive `lineTo` points form polylines whose width is in world units; they are only
	tesselated in the XY plane (as seen from above).
	Lines are not lit and do not cast shadows.

	```haxe
	var g = new h3d.scene.Graphics(s3d);
	g.lineStyle(2, 0xFF0000);
	g.moveTo(0, 0, 0);
	g.lineTo(0, 0, 10);
	```

new.haxe_doc:
Creates a wireframe box.
		@param color The line color, in `0xRRGGBB` format (red by default, the alpha byte is ignored).
		@param bounds The box bounds in local space, or `null` for a unit box centered on the origin.
		@param depth If `false`, the box is always drawn on top of the scene (depth test disabled).
		@param parent An optional parent object.

Creates an orbit controller.
		@param distance The initial distance to the target.
		@param parent The parent object, usually the scene.

class.haxe_doc:
A camera controller orbiting around a target, as in 3D editors:
	- right button drag: pans the target;
	- middle button drag (or Alt + left button drag): rotates around the target;
	- mouse wheel: zooms (see `enableZoom`);
	- arrow keys, WASD or ZQSD while dragging: move the target horizontally.

	```haxe
	new h3d.scene.CameraController.OrbitCameraController(s3d).loadFromCamera();
	```

new.haxe_doc:
Creates a first person controller.
		@param distance The initial distance between the camera and the point it looks at.
		@param parent The parent object, usually the scene.

class.haxe_doc:
A free flying "first person" camera controller:
	- right button drag: looks around;
	- while holding the right or middle button: arrow keys or ZQSD move forward/backward/sideways (W, S and D also work),
	  A moves down and E moves up;
	- mouse wheel while holding a button: changes `moveSpeed`.

new.haxe_doc:
Creates a wireframe capsule.
		@param color The line color, in `0xRRGGBB` format (red by default, the alpha byte is ignored).
		@param radius The capsule radius.
		@param length The length of the cylindrical part along the X axis.
		@param depth If `false`, the capsule is always drawn on top of the scene (depth test disabled).
		@param parent An optional parent object.

Creates an interactive using the given collision shape.
		@param shape The collision shape, see `shape`.
		@param parent An optional parent object.

getShadowDirection.haxe_doc:
Returns the direction used to cast shadows, or `null` if this light does not cast directional shadows.
		Used by `LightSystem.initLights` to select the scene shadow light.
		@param v An optional vector to store the result in, avoiding an allocation.

emit.haxe_doc:
Emits the passes of material `mat` for object `obj`, so that they are drawn this frame.
		Called by objects in their `Object.emit` implementation.
		@param index The index of the material in the object (for instance a material group of a `MultiMaterial`).

computeDispatch.haxe_doc:
Runs a compute shader, or the shaders set by `computeList`, with the given number of work groups (at most 65535 per axis).
		Can be called outside of a frame rendering: the context is then started and ended around the dispatch.
		@param barrier Inserts a memory barrier after the dispatch.

setJointRelPosition.haxe_doc:
Overrides the transform of joint `name` relative to its parent. Animations overwrite it when they update the joint.
		@param additive If `true`, sets a transform applied on top of the animated pose instead, which is kept
		until set to `null`.

new.haxe_doc:
Creates a skinned mesh.
		@param s The skin data (skeleton and skinned primitive), or `null` to set it later with `setSkinData`.
		@param mat The materials.
		@param parent An optional parent object.

Creates a wireframe sphere.
		@param color The line color, in `0xRRGGBB` format (red by default, the alpha byte is ignored).
		@param radius The sphere radius.
		@param depth If `false`, the sphere is always drawn on top of the scene (depth test disabled).
		@param parent An optional parent object.

add.haxe_doc:
Adds an instance of `model` at the given world position.
		@param scale A uniform scale.
		@param rotation A rotation around the Z axis, in radians.

new.haxe_doc:
Creates an empty world.
		@param chunkSize The size of a chunk, in world units.
		@param parent The parent object.
		@param autoCollect If `true`, the world registers `garbage` as the GPU memory garbage collector of the engine.

class.haxe_doc:
A static world made of many model instances, split in square chunks on the XY plane.

	The instances of each chunk are merged in a few big meshes (one per material) when the chunk becomes visible,
	and their textures packed in big textures, which makes drawing many static models fast.
	The meshes of the least recently visible chunks are released when GPU memory is needed (see `garbage`).

	```haxe
	var world = new h3d.scene.World(64, s3d);
	var tree = world.loadModel(hxd.Res.tree);
	for( i in 0...1000 )
		world.add(tree, Math.random() * 512, Math.random() * 512, 0, 1, Math.random() * Math.PI * 2);
	world.done();
	```

new.haxe_doc:
Creates a directional light, with a `priority` of 100.
		@param dir The light direction (towards which the light shines).
		@param parent An optional parent object.

class.haxe_doc:
A directional light of the forward renderer, such as the sun: its rays are parallel and it has no position.

	The light direction is the X axis of the object (see `Object.setDirection`).

	```haxe
	var light = new h3d.scene.fwd.DirLight(new h3d.Vector(0.5, 0.5, -0.5), s3d);
	light.color.set(1, 1, 1);
	```

new.haxe_doc:
Creates a directional light.
		@param dir The light direction (towards which the light shines).
		@param parent An optional parent object.
		@param cascade If `true`, uses cascaded shadow maps (`h3d.pass.CascadeShadowMap`), better for large scenes.
		Otherwise uses a single `h3d.pass.DirShadowMap`.

m.e:
{
	@const var samplesBits:Int;
	function _reversebits(i:Int):Int {
		var r = (i << 16) | (i >>> 16);
		r = ((r & 0x00ff00ff) << 8) | ((r & 0xff00ff00) >>> 8);
		r = ((r & 0x0f0f0f0f) << 4) | ((r & 0xf0f0f0f0) >>> 4);
		r = ((r & 0x33333333) << 2) | ((r & 0xcccccccc) >>> 2);
		r = ((r & 0x55555555) << 1) | ((r & 0xaaaaaaaa) >>> 1);
		return r;
	};
	function hammersley(i:Int, max:Int):Vec2 {
		var ri = _reversebits(i) * 2.3283064365386963e-10;
		return vec2(float(i) / float(max), ri);
	};
	function importanceSampleGGX(roughness:Float, p:Vec2, n:Vec3):Vec3 {
		var a = roughness * roughness;
		var phi = 2 * PI * p.x;
		var cosT = sqrt((1 - p.y) / (1 + (a * a - 1) * p.y)).min(1.);
		var sinT = sqrt(1 - cosT * cosT);
		var ltan = vec3(sinT * cos(phi), sinT * sin(phi), cosT);
		var up = abs(n.z) < 0.999 ? vec3(0, 0, 1) : vec3(1, 0, 0);
		var tanX = normalize(cross(up, n));
		var tanY = normalize(cross(n, tanX));
		return (tanX * ltan.x + tanY * ltan.y + n * ltan.z).normalize();
	};
}

{
	@param var faceMatrix:Mat3;
	@param var envMap:SamplerCube;
	@const var isSpecular:Bool;
	@const var isSRGB:Bool;
	@param var roughness:Float;
	@param var cubeSize:Float;
	@param var cubeScaleFactor:Float;
	@param var hdrMax:Float;
	@:import h3d.shader.ColorSpaces;
	function cosineWeightedSampling(p:Vec2, n:Vec3):Vec3 {
		var sq = sqrt(1 - p.x);
		var alpha = 2 * PI * p.y;
		var ltan = vec3(sq * cos(alpha), sq * sin(alpha), sqrt(p.x));
		var up = abs(n.z) < 0.999 ? vec3(0, 0, 1) : vec3(1, 0, 0);
		var tanX = normalize(cross(up, n));
		var tanY = normalize(cross(n, tanX));
		return (tanX * ltan.x + tanY * ltan.y + n * ltan.z).normalize();
	};
	function getNormal():Vec3 {
		var d = input.uv * 2. - 1.;
		if (isSpecular) {
			d += cubeScaleFactor * (d * d * d);
		};
		return (vec3(d, 1.) * faceMatrix).normalize();
	};
	function gammaCorrect(color:Vec3):Vec3 {
		return isSRGB ? color : srgb2linear(color);
	};
	function fragment() {
		var color = vec3(0.);
		var n = getNormal();
		var totalWeight = 1e-10;
		var numSamples = 1 << samplesBits;
		for (i  in  0 ... numSamples) {
			var p = hammersley(i, numSamples);
			var l:Vec3;
			if (isSpecular) {
				var h = importanceSampleGGX(roughness, p, n);
				var v = n;
				l = reflect(-v, h).normalize();
			} else {
				l = cosineWeightedSampling(p, n);
			};
			var amount = n.dot(l).saturate();
			if (amount > 0) {
				var envColor = gammaCorrect(min(envMap.get(l).rgb, hdrMax));
				if (!isSpecular) amount = 1.0;
				color += envColor * amount;
				totalWeight += amount;
			};
		};
		output.color = vec4(color / totalWeight, 1.);
	};
}

{
	function GGX(NdotV:Float, roughness:Float):Float {
		var k = (roughness * roughness) * 0.5;
		return NdotV / (NdotV * (1.0 - k) + k);
	};
	function G_Smith(roughness:Float, nDotV:Float, nDotL:Float):Float {
		return GGX(nDotL, roughness) * GGX(nDotV, roughness);
	};
	function fragment() {
		var roughness = input.uv.x;
		var NoV = input.uv.y;
		var v = vec3(sqrt(1.0 - NoV * NoV), 0., NoV);
		var n = vec3(0, 0, 1.);
		var numSamples = 1 << samplesBits;
		var a = 0., b = 0.;
		for (i  in  0 ... numSamples) {
			var xi = hammersley(i, numSamples);
			var h = importanceSampleGGX(roughness, xi, n);
			var l = reflect(-v, h);
			var NoL = saturate(dot(n, l));
			var NoH = saturate(dot(n, h));
			var VoH = saturate(dot(v, h));
			if (NoL > 0) {
				var g = G_Smith(roughness, NoV, NoL);
				var gvis = g * VoH / (NoH * NoV);
				var fresnel = pow(1 - VoH, 5.);
				a += (1 - fresnel) * gvis;
				b += fresnel * gvis;
			};
		};
		output.color = vec4(a / numSamples, b / numSamples, 0, 1);
	};
}

{
	@param var texture:Sampler2D;
	@param var faceMatrix:Mat3;
	@param var threshold:Float;
	@param var aboveThresholdScale:Float;
	function getNormal():Vec3 {
		var d = input.uv * 2. - 1.;
		return (vec3(d, 1.) * faceMatrix).normalize();
	};
	function fragment() {
		var n = getNormal();
		var uv = vec2(atan(n.y, n.x), asin(-n.z));
		uv *= vec2(0.1591, 0.3183);
		uv += 0.5;
		pixelColor = texture.get(uv);
		if (max(max(pixelColor.r, pixelColor.g), pixelColor.b) > threshold) pixelColor *= aboveThresholdScale;
	};
}

{
	@param var source:SamplerCube;
	function fragment() {
		var fovX = PI * 2;
		var fovY = PI;
		var hOffset = (2.0 * PI - fovX) * 0.5;
		var vOffset = (PI - fovY) * 0.5;
		var hAngle = hOffset + calculatedUV.x * fovX;
		var vAngle = vOffset + calculatedUV.y * fovY;
		var n = vec3(0);
		n.x = sin(vAngle) * sin(hAngle);
		n.y = cos(vAngle);
		n.z = sin(vAngle) * cos(hAngle);
		n = n.normalize();
		pixelColor = vec4(source.get(n).rgb, 1.0);
		pixelColor = vec4(1, 0, 0, 1);
	};
}

equiToCube.haxe_doc:
Converts an equirectangular texture (twice as wide as high) to a cube map. Cube textures are returned unchanged.
		@param threshold The color value above which `scale` is applied.
		@param scale The multiplier applied to the colors above `threshold`.

new.haxe_doc:
Creates an environment from `src`, which can be a cube map already prepared or a 2D equirectangular map that
		will be turned into a cube map. Call `compute` to build the lighting textures.
		@param diffSize The size of the diffuse irradiance cube map faces.
		@param specSize The size of the specular cube map faces.
		@param sampleBits The number of samples used to compute the textures is `2^sampleBits`.

class.haxe_doc:
The environment lighting of the PBR renderer (image based lighting): the sky texture and the diffuse and specular
	lighting textures computed from it, used for the indirect lighting and the reflections.

	```haxe
	var env = new h3d.scene.pbr.Environment(hxd.Res.sky.toTexture());
	env.compute();
	cast(s3d.renderer, h3d.scene.pbr.Renderer).env = env;
	```

