{
	@input var input:{ var uv : Vec2};
	@const @param var useSourceUVs:Bool = true;
	@const @param var blendBetweenFrames:Bool = true;
	@param var texture:Sampler2D;
	var pixelColor:Vec4;
	var animatedUV:Vec2;
	var animatedUV2:Vec2;
	@global var global:{ var time : Float};
	@perInstance @param var startFrame:Float = 0.0;
	@param var speed:Float;
	@param var frameDivision:Vec2;
	@param var totalFrames:Float;
	@perInstance @param var startTime:Float;
	@const var loop:Bool;
	@private var blendFactor:Float;
	var textureColor:Vec4;
	var calculatedUV:Vec2;
	function vertex() {
		var frame = (global.time - startTime) * speed + float(int(startFrame));
		blendFactor = frame.fract();
		frame = floor(frame);
		if (loop) frame %= totalFrames else frame = min(frame, totalFrames - 1);
		var nextFrame = if (loop) (frame + 1) % totalFrames else min(frame + 1, totalFrames - 1);
		var delta = vec2(frame % frameDivision.x, float(int(frame / frameDivision.x)));
		animatedUV = (delta) / frameDivision;
		var delta = vec2(nextFrame % frameDivision.x, float(int(nextFrame / frameDivision.x)));
		animatedUV2 = (delta) / frameDivision;
	};
	function __init__fragment() {
		textureColor = mix(texture.get((useSourceUVs ? input.uv : calculatedUV) / frameDivision + animatedUV), texture.get((useSourceUVs ? input.uv : calculatedUV) / frameDivision + animatedUV2), blendBetweenFrames ? blendFactor : 0.0);
	};
	function fragment() {
		pixelColor *= textureColor;
	};
}

{
	@const var IS_LOCAL:Bool = false;
	@param var invTransform:Mat4;
	@param var transform:Mat4;
	@param var prevTransform:Mat4;
	var modelView:Mat4;
	var modelViewInverse:Mat4;
	var prevModelView:Mat4;
	function __init__() {
		if (IS_LOCAL) {
			modelView = transform * modelView;
			modelViewInverse = modelViewInverse * invTransform;
			prevModelView = prevTransform * prevModelView;
		} else {
			modelView = modelView * transform;
			modelViewInverse = invTransform * modelViewInverse;
			prevModelView = prevModelView * prevTransform;
		};
	};
}

{
	@input var input:{ var position : Vec2; var uv : Vec2; var color : Vec4};
	var output:{ var position : Vec4; var color : Vec4};
	@global var time:Float;
	@param var zValue:Float;
	@param var texture:Sampler2D;
	var spritePosition:Vec4;
	var absolutePosition:Vec4;
	var pixelColor:Vec4;
	var textureColor:Vec4;
	@var var calculatedUV:Vec2;
	@const var isRelative:Bool;
	@param var color:Vec4;
	@param var absoluteMatrixA:Vec3;
	@param var absoluteMatrixB:Vec3;
	@param var filterMatrixA:Vec3;
	@param var filterMatrixB:Vec3;
	@const var hasUVPos:Bool;
	@param var uvPos:Vec4;
	@const var killAlpha:Bool;
	@const var pixelAlign:Bool;
	@param var halfPixelInverse:Vec2;
	@param var viewportA:Vec3;
	@param var viewportB:Vec3;
	var outputPosition:Vec4;
	function __init__() {
		spritePosition = vec4(input.position, zValue, 1);
		if (isRelative) {
			absolutePosition.x = vec3(spritePosition.xy, 1).dot(absoluteMatrixA);
			absolutePosition.y = vec3(spritePosition.xy, 1).dot(absoluteMatrixB);
			absolutePosition.zw = spritePosition.zw;
		} else absolutePosition = spritePosition;
		calculatedUV = hasUVPos ? input.uv * uvPos.zw + uvPos.xy : input.uv;
		pixelColor = isRelative ? color * input.color : input.color;
		textureColor = texture.get(calculatedUV);
		pixelColor *= textureColor;
	};
	function vertex() {
		var tmp = vec3(absolutePosition.xy, 1);
		tmp = vec3(tmp.dot(filterMatrixA), tmp.dot(filterMatrixB), 1);
		outputPosition = vec4(tmp.dot(viewportA), tmp.dot(viewportB), absolutePosition.zw);
		if (pixelAlign) outputPosition.xy -= halfPixelInverse;
		output.position = outputPosition;
	};
	function fragment() {
		if (killAlpha && pixelColor.a < 0.001) discard;
		output.color = pixelColor;
	};
}

{
	@global var camera:{ var view : Mat4; var proj : Mat4; var position : Vec3; var projFlip : Float; var projDiag : Vec3; var viewProj : Mat4; var previousViewProj : Mat4; var inverseViewProj : Mat4; var zNear : Float; var zFar : Float; @var
	var dir : Vec3; var jitterOffsets : Vec4};
	@global var global:{ var time : Float; var pixelSize : Vec2; @perObject
	var modelView : Mat4; @perObject
	var modelViewInverse : Mat4; @perObject
	var previousModelView : Mat4};
	@input var input:{ var position : Vec3; var normal : Vec3};
	var output:{ var position : Vec4; var color : Vec4; var depth : Float; var normal : Vec3; var worldDist : Float; var velocity : Vec2};
	var relativePosition:Vec3;
	var transformedPosition:Vec3;
	var previousTransformedPosition:Vec3;
	var pixelTransformedPosition:Vec3;
	var transformedNormal:Vec3;
	var projectedPosition:Vec4;
	var previousProjectedPosition:Vec4;
	var pixelColor:Vec4;
	var depth:Float;
	var ndcPosition:Vec2;
	var previousNdcPosition:Vec2;
	var screenUV:Vec2;
	var specPower:Float;
	var specColor:Vec3;
	var worldDist:Float;
	var pixelVelocity:Vec2;
	var modelView:Mat4;
	var modelViewInverse:Mat4;
	var prevModelView:Mat4;
	@param var color:Vec4;
	@range(0, 100) @param var specularPower:Float;
	@range(0, 10) @param var specularAmount:Float;
	@param var specularColor:Vec3;
	@const var IS_STATIC:Bool = false;
	function __init__() {
		relativePosition = input.position;
		modelView = global.modelView;
		modelViewInverse = global.modelViewInverse;
		transformedPosition = relativePosition * modelView.mat3x4();
		projectedPosition = vec4(transformedPosition, 1) * camera.viewProj;
		prevModelView = IS_STATIC ? modelView : global.previousModelView;
		previousTransformedPosition = relativePosition * prevModelView.mat3x4();
		previousProjectedPosition = vec4(previousTransformedPosition, 1) * camera.previousViewProj;
		camera.dir = (camera.position - transformedPosition).normalize();
		pixelColor = color;
		specPower = specularPower;
		specColor = specularColor * specularAmount;
		screenUV = screenToUv(projectedPosition.xy / projectedPosition.w);
		depth = projectedPosition.z / projectedPosition.w;
	};
	function __init__vertex() {
		transformedNormal = (input.normal * modelView.mat3()).normalize();
		worldDist = length(transformedPosition - camera.position) / camera.zFar;
	};
	function __init__fragment() {
		transformedNormal = transformedNormal.normalize();
		ndcPosition = projectedPosition.xy / projectedPosition.w;
		previousNdcPosition = previousProjectedPosition.xy / previousProjectedPosition.w;
		screenUV = screenToUv(ndcPosition);
		depth = projectedPosition.z / projectedPosition.w;
		specPower = specularPower;
		specColor = specularColor * specularAmount;
		ndcPosition -= camera.jitterOffsets.xy;
		previousNdcPosition -= camera.jitterOffsets.zw;
		pixelVelocity = (previousNdcPosition - ndcPosition) * vec2(0.5, -0.5);
	};
	function vertex() {
		output.position = projectedPosition * vec4(1, camera.projFlip, 1, 1);
		pixelTransformedPosition = transformedPosition;
	};
	function fragment() {
		output.color = pixelColor;
		output.depth = depth;
		output.normal = transformedNormal;
		output.worldDist = worldDist;
		output.velocity = pixelVelocity;
	};
}

{
	@input var input:{ var position : Vec3; var normal : Vec3; var weights : Vec3; var indexes : Bytes4};
	var relativePosition:Vec3;
	@param var shapeCount:Int;
	@param var vcount:Int;
	@param var offsets:StorageBuffer<Float>;
	@param var weights:StorageBuffer<Float>;
	function vertex() {
		for (idx  in  0 ... shapeCount) {
			var offsetPos = vec3(offsets[(idx * vcount * 3) + (vertexID * 3)], offsets[(idx * vcount * 3) + (vertexID * 3) + 1], offsets[(idx * vcount * 3) + (vertexID * 3) + 2]);
			relativePosition = relativePosition + offsetPos * weights[idx];
		};
	};
}

{
	@param var texture:Sampler2D;
	@param var power:Float;
	@param var amount:Float;
	function fragment() {
		var c = texture.get(input.uv);
		var lum = c.rgb.dot(vec3(0.2126, 0.7152, 0.0722));
		output.color = vec4(c.rgb * lum.pow(power) * amount * c.a, c.a);
	};
}

{
	@param var inverseProj:Mat4;
	@param var texture:Sampler2D;
	@param var depthTexture:Sampler2D;
	@param @const var Quality:Int;
	@param @const var isDepth:Bool;
	@param var values:Array<Float,Quality>;
	@param var offsets:Array<Float,Quality>;
	@param var pixel:Vec2;
	@const var hasFixedColor:Bool;
	@const var smoothFixedColor:Bool;
	@param var fixedColor:Vec4;
	@param @const var isDepthDependant:Bool;
	@param var depthThreshold:Float = 1.0;
	@param var depthThresholdMaxDist:Float = 0.0;
	@param @const var isCube:Bool;
	@param var cubeTexture:SamplerCube;
	@param var cubeDir:Mat3;
	function scaleThreshold(z:Float):Float {
		var t = depthThreshold;
		if (depthThresholdMaxDist > 0.0) t *= 1.0 + max(z - depthThresholdMaxDist, 0.0);
		return t;
	};
	function fragment() {
		if (isDepthDependant) {
			var dimensions = texture.size();
			var invDimensions = 1.0 / dimensions;
			var coord = fragCoord.xy;
			var fragUV = coord.xy * invDimensions;
			var p = getViewPosition(fragUV);
			var minZ = p.z;
			var c = texture.get(fragUV);
			var color = vec4(0, 0, 0, 0);
			var isEdge = false;
			@unroll for (i  in  -Quality ... Quality + 1) {
				var curCoord = floor(coord + (pixel * dimensions) * i) + vec2(0.5);
				var nearestUV = curCoord * invDimensions;
				var pcur = getViewPosition(nearestUV);
				var d = abs(pcur.z - p.z);
				isEdge = isEdge || (d > scaleThreshold(min(pcur.z, p.z)));
			};
			@unroll for (i  in  -Quality + 1 ... Quality) {
				var curCoord = floor(coord + (pixel * dimensions) * offsets[i < 0 ? -i : i] * i) + vec2(0.5);
				var nearestUV = curCoord * invDimensions;
				var uv = fragUV + pixel * offsets[i < 0 ? -i : i] * i;
				var ccur = texture.get((isEdge) ? nearestUV : uv);
				var pcur = getViewPosition(nearestUV);
				var d = abs(pcur.z - p.z);
				c = (d > scaleThreshold(min(pcur.z, p.z))) ? c : ccur;
				color += c * values[i < 0 ? -i : i];
			};
			pixelColor = color;
		} else if (isDepth) {
			var val = 0.;
			@unroll for (i  in  -Quality + 1 ... Quality) {
				if (isCube) val += unpack(cubeTexture.get(vec3((input.uv + pixel * offsets[i < 0 ? -i : i] * i) * 2.0 - 1.0, 1) * cubeDir)) * values[i < 0 ? -i : i] else val += unpack(texture.get(input.uv + pixel * offsets[i < 0 ? -i : i] * i)) * values[i < 0 ? -i : i];
			};
			pixelColor = pack(val.min(0.9999999));
		} else {
			var color = vec4(0, 0, 0, 0);
			@unroll for (i  in  -Quality + 1 ... Quality) {
				if (isCube) color += cubeTexture.get(vec3((input.uv + pixel * offsets[i < 0 ? -i : i] * i) * 2.0 - 1.0, 1) * cubeDir) * values[i < 0 ? -i : i] else color += texture.get(input.uv + pixel * offsets[i < 0 ? -i : i] * i) * values[i < 0 ? -i : i];
			};
			pixelColor = color;
		};
		if (hasFixedColor) {
			if (smoothFixedColor) pixelColor.a *= fixedColor.a else pixelColor.a = fixedColor.a * float(pixelColor.a > 0);
			pixelColor.rgb = fixedColor.rgb * pixelColor.a;
		};
	};
	function getViewPosition(uv:Vec2):Vec3 {
		var depth = depthTexture.get(uv).r;
		var temp = vec4(uvToScreen(uv), depth, 1) * inverseProj;
		var originWS = temp.xyz / temp.w;
		return originWS;
	};
}

{
	@:extends h3d.shader.ShadowSampling;
	var pixelColor:Vec4;
	@global var camera:{ var view : Mat4};
	@const var enable:Bool;
	@const(2) var SAMPLING_MODE:Int;
	@const var DEBUG:Bool;
	@const var BLEND:Bool;
	@param var shadowPower:Float;
	@param var pcfScale:Float;
	var transformedPosition:Vec3;
	var shadow:Float;
	var dirShadow:Float;
	@param var cascadeShadowMaps:Sampler2DArray;
	@param var cascadeScales:Array<Vec4,MAX_CASCADE_COUNT>;
	@param var cascadeOffsets:Array<Vec4,MAX_CASCADE_COUNT>;
	@param var cascadeDebugs:Array<Vec4,MAX_CASCADE_COUNT>;
	@param var cascadeCount:Int;
	@param var cascadeViewProj:Mat3x4;
	@param var cascadeTransitionFraction:Float;
	function fragment() {
		if (enable) {
			var shadowValue = 1.0;
			var color = vec3(0);
			var viewZ = (transformedPosition * camera.view.mat3x4()).z;
			var shouldContinue = true;
			@unroll for (i  in  0 ... MAX_CASCADE_COUNT) if (i < cascadeCount) {
				if (shouldContinue && viewZ <= cascadeScales[i].w) {
					shouldContinue = false;
					var shadowPos0 = transformedPosition * cascadeViewProj;
					var shadowPos = (i == 0) ? shadowPos0 : cascadeShadowPos(shadowPos0, cascadeScales[i].xyz, cascadeOffsets[i].xyz);
					shadowValue = sampleCascadeArray(cascadeShadowMaps, i, shadowPos, 0.0, pcfScale, shadowPower, transformedPosition, SAMPLING_MODE);
					color = cascadeDebugs[i].rgb;
					if (BLEND) {
						var blendFactor = cascadeBlendFactor(viewZ, cascadeScales[i].w, cascadeTransitionFraction);
						if (blendFactor > 0.0) {
							if (i < MAX_CASCADE_COUNT - 1 && i < cascadeCount - 1) {
								var nextShadowPos = cascadeShadowPos(shadowPos0, cascadeScales[i + 1].xyz, cascadeOffsets[i + 1].xyz);
								var nextShadow = sampleCascadeArray(cascadeShadowMaps, i + 1, nextShadowPos, 0.0, pcfScale, shadowPower, transformedPosition, SAMPLING_MODE);
								shadowValue = nextShadow * blendFactor + shadowValue * (1 - blendFactor);
								var nextColor = cascadeDebugs[i + 1].rgb;
								color = nextColor * blendFactor + color * (1 - blendFactor);
							} else {
								shadowValue = blendFactor + shadowValue * (1 - blendFactor);
								color = color * (1 - blendFactor);
							};
						};
					};
				};
			};
			if (DEBUG) pixelColor = vec4(color, 1.0) else {
				shadow = shadowValue;
				dirShadow = shadow;
			};
		};
	};
}

{
	var pixelColor:Vec4;
	@param var width:Float;
	@param var height:Float;
	var calculatedUV:Vec2;
	@input var input:{ var uv : Vec2};
	function vertex() {
		calculatedUV = input.uv;
	};
	function fragment() {
		if (((calculatedUV.fract().x - 0.5) * (calculatedUV.fract().y - 0.5)) > 0.0) {
			pixelColor.rgb = vec3(1.0);
		} else {
			pixelColor.rgb = vec3(0.0);
