	function esmFilter(depth:Float, zMax:Float, bias:Float, power:Float):Float {
		return exp(power * ((depth + bias).min(zMax) - zMax)).saturate();
	};
	function dirShadowPos(pos:Vec3, m:Mat3x4):Vec3 {
		var p = pos * m;
		return vec3(screenToUv(p.xy), p.z.saturate());
	};
	function spotShadowPos(pos:Vec3, m:Mat4):Vec3 {
		var p = vec4(pos, 1.0) * m;
		p.xyz /= p.w;
		return vec3(screenToUv(p.xy), p.z);
	};
	function shadowPcf(shadowMap:Sampler2D, uv:Vec2, zMax:Float, bias:Float, pcfScale:Float, pos:Vec3):Float {
		var cs = poissonRotation(pos);
		var shadow = 1.0;
		@unroll for (i  in  0 ... PCF_SAMPLES) {
			var o = poissonOffset(i, cs, pcfScale);
			var compare = insideShadow(uv) ? compareDepth(shadowMap.getLod(uv + o, 0).r, zMax, bias) : 1.0;
			shadow -= compare > 0.0 ? 0.0 : 1.0 / PCF_SAMPLES;
		};
		return shadow;
	};
	function cubeShadowPcf(shadowMap:SamplerCube, dir:Vec3, zMax:Float, range:Float, bias:Float, pcfScale:Float):Float {
		var shadow = 1.0;
		if (range >= zMax) {
			var sampleStrength = 1.0 / CUBE_PCF_SAMPLES;
			@unroll for (i  in  0 ... CUBE_PCF_SAMPLES) {
				var offset = offsetDirections[i] * pcfScale;
				var depth = shadowMap.getLod(dir + offset, 0).r * range;
				if (zMax - bias > depth) shadow -= sampleStrength;
			};
		};
		return saturate(shadow);
	};
	function shadowArrayPcf(shadowMap:Sampler2DArray, uv:Vec2, layer:Int, zMax:Float, bias:Float, pcfScale:Float, pos:Vec3):Float {
		var cs = poissonRotation(pos);
		var shadow = 1.0;
		@unroll for (i  in  0 ... PCF_SAMPLES) {
			var o = poissonOffset(i, cs, pcfScale);
			var compare = insideShadow(uv) ? compareDepth(shadowMap.getLod(vec3(uv + o, layer), 0).r, zMax, bias) : 1.0;
			shadow -= compare > 0.0 ? 0.0 : 1.0 / PCF_SAMPLES;
		};
		return shadow;
	};
	function sampleShadow(shadowMap:Sampler2D, uv:Vec2, zMax:Float, bias:Float, pcfScale:Float, esmPower:Float, worldPos:Vec3, samplingMode:Int):Float {
		var shadow = 1.0;
		if (insideShadow(uv)) {
			if (samplingMode == SAMPLING_PCF) shadow = shadowPcf(shadowMap, uv, zMax, bias, pcfScale, worldPos) else if (samplingMode == SAMPLING_ESM) shadow = esmFilter(shadowMap.getLod(uv, 0).r, zMax, bias, esmPower) else if (samplingMode == SAMPLING_NONE) shadow = compareDepth(shadowMap.getLod(uv, 0).r, zMax, bias);
		};
		return saturate(shadow);
	};
	function sampleCubeShadow(shadowMap:SamplerCube, dir:Vec3, zMax:Float, range:Float, bias:Float, pcfScale:Float, esmPower:Float, samplingMode:Int):Float {
		var shadow = 1.0;
		if (samplingMode == SAMPLING_PCF) shadow = cubeShadowPcf(shadowMap, dir, zMax, range, bias, pcfScale) else if (samplingMode == SAMPLING_ESM) shadow = esmFilter(shadowMap.getLod(dir, 0).r * range, zMax, bias, esmPower) else if (samplingMode == SAMPLING_NONE) shadow = compareDepth(shadowMap.getLod(dir, 0).r * range, zMax, bias);
		return saturate(shadow);
	};
	var MAX_CASCADE_COUNT:Int = 4;
	function cascadeBlendFactor(viewZ:Float, blendEnd:Float, transitionFraction:Float):Float {
		var blendSize = blendEnd * transitionFraction;
		var blendStart = blendEnd - blendSize;
		return (viewZ - blendStart) / blendSize;
	};
	function cascadeShadowPos(shadowPos0:Vec3, scale:Vec3, offset:Vec3):Vec3 {
		return shadowPos0 * scale + offset;
	};
	function sampleCascadeArray(shadowMap:Sampler2DArray, layer:Int, shadowPos:Vec3, bias:Float, pcfScale:Float, esmPower:Float, worldPos:Vec3, samplingMode:Int):Float {
		var zMax = shadowPos.z.saturate();
		var uv = shadowPos.xy;
		uv.y = 1.0 - uv.y;
		var shadow = 1.0;
		if (samplingMode == SAMPLING_PCF) shadow = shadowArrayPcf(shadowMap, uv, layer, zMax, bias, pcfScale, worldPos) else if (samplingMode == SAMPLING_ESM) shadow = esmFilter(shadowMap.getLod(vec3(uv, layer), 0).r, zMax, bias, esmPower) else if (samplingMode == SAMPLING_NONE) shadow = compareDepth(shadowMap.getLod(vec3(uv, layer), 0).r, zMax, bias);
		return saturate(shadow);
	};
}

{
	@:import h3d.shader.Base2d;
	@const var channel:Int = 0;
	@const var autoSmoothing:Bool = false;
	@param var alphaCutoff:Float = 0.5;
	@param var smoothing:Float = 0.04166666666666666666666666666667;
	function median(r:Float, g:Float, b:Float):Float {
		return max(min(r, g), min(max(r, g), b));
	};
	function fragment() {
		var textureSample:Vec4 = textureColor;
		var distance:Float;
		distance = if (channel == 0) textureSample.r else if (channel == 1) textureSample.g else if (channel == 2) textureSample.b else if (channel == 3) textureSample.a else median(textureSample.r, textureSample.g, textureSample.b);
		var smoothVal = autoSmoothing ? abs(fwidth(distance) * 0.5) : smoothing;
		textureColor = vec4(1.0, 1.0, 1.0, smoothstep(alphaCutoff - smoothVal, alphaCutoff + smoothVal, distance));
	};
}

{
	@global var time:Float;
	@param var speed:Float;
	@param var frequency:Float;
	@param var amplitude:Float;
	var calculatedUV:Vec2;
	function fragment() {
		calculatedUV.x += sin(calculatedUV.y * frequency + time * speed) * amplitude;
	};
}

{
	var boneMatrixX:Mat3x4;
	var boneMatrixY:Mat3x4;
	var boneMatrixZ:Mat3x4;
	var boneMatrixW:Mat3x4;
	var skinWeights:Vec4;
	function applySkinPoint(p:Vec3):Vec3 {
		var transformed = (p * boneMatrixX) * skinWeights.x + (p * boneMatrixY) * skinWeights.y + (p * boneMatrixZ) * skinWeights.z;
		if (skinWeights.w > 0.0) transformed += (p * boneMatrixW) * skinWeights.w;
		return transformed;
	};
	function applySkinVec(v:Vec3):Vec3 {
		var transformed = (v * mat3(boneMatrixX)) * skinWeights.x + (v * mat3(boneMatrixY)) * skinWeights.y + (v * mat3(boneMatrixZ)) * skinWeights.z;
		if (skinWeights.w > 0.0) transformed += (v * mat3(boneMatrixW)) * skinWeights.w;
		return transformed;
	};
}

{
	var relativePosition:Vec3;
	var transformedPosition:Vec3;
	var transformedNormal:Vec3;
	@const(1024) var BUFFER_SIZE:Int;
	@const @param var fourBonesByVertex = false;
	@param var bonesMatrixes:Buffer<Vec4,BUFFER_SIZE>;
	@param var prevBonesMatrixes:Buffer<Vec4,BUFFER_SIZE>;
	function getBoneMatrix(index:Float):Mat3x4 {
		var i = int(index) * 3;
		return mat3x4(bonesMatrixes[i], bonesMatrixes[i + 1], bonesMatrixes[i + 2]);
	};
	function getPrevBoneMatrix(index:Float):Mat3x4 {
		var i = int(index) * 3;
		return mat3x4(prevBonesMatrixes[i], prevBonesMatrixes[i + 1], prevBonesMatrixes[i + 2]);
	};
}

{
	@:import h3d.shader.Skin.Utils;
	@input var input:{ var position : Vec3; var normal : Vec3; var weights : Vec3; var indexes : Bytes4};
	var previousTransformedPosition:Vec3;
	function vertex() {
		boneMatrixX = getBoneMatrix(input.indexes.x);
		boneMatrixY = getBoneMatrix(input.indexes.y);
		boneMatrixZ = getBoneMatrix(input.indexes.z);
		boneMatrixW = getBoneMatrix(input.indexes.w);
		skinWeights = vec4(input.weights, 0.0);
		if (fourBonesByVertex) skinWeights.w = 1 - (input.weights.x + input.weights.y + input.weights.z);
		transformedPosition = applySkinPoint(relativePosition);
		transformedNormal = applySkinVec(input.normal);
		transformedNormal = normalize(transformedNormal);
		var prevPosition = (relativePosition * getPrevBoneMatrix(input.indexes.x)) * skinWeights.x + (relativePosition * getPrevBoneMatrix(input.indexes.y)) * skinWeights.y + (relativePosition * getPrevBoneMatrix(input.indexes.z)) * skinWeights.z;
		if (skinWeights.w > 0.0) prevPosition += (relativePosition * getPrevBoneMatrix(input.indexes.w)) * skinWeights.w;
		previousTransformedPosition = prevPosition;
	};
}

{
	@:import h3d.shader.Skin.Utils;
	@input var input:{ var position : Vec3; var normal : Vec3; var tangent : Vec3; var weights : Vec3; var indexes : Bytes4};
	var transformedTangent:Vec4;
	var previousTransformedPosition:Vec3;
	function vertex() {
		boneMatrixX = getBoneMatrix(input.indexes.x);
		boneMatrixY = getBoneMatrix(input.indexes.y);
		boneMatrixZ = getBoneMatrix(input.indexes.z);
		boneMatrixW = getBoneMatrix(input.indexes.w);
		skinWeights = vec4(input.weights, 0.0);
		if (fourBonesByVertex) skinWeights.w = 1 - (input.weights.x + input.weights.y + input.weights.z);
		transformedPosition = applySkinPoint(relativePosition);
		transformedNormal = applySkinVec(input.normal);
		transformedTangent.xyz = applySkinVec(input.tangent.xyz);
		transformedNormal = normalize(transformedNormal);
		transformedTangent.xyz = normalize(transformedTangent.xyz);
		var prevPosition = (relativePosition * getPrevBoneMatrix(input.indexes.x)) * skinWeights.x + (relativePosition * getPrevBoneMatrix(input.indexes.y)) * skinWeights.y + (relativePosition * getPrevBoneMatrix(input.indexes.z)) * skinWeights.z;
		if (skinWeights.w > 0.0) prevPosition += (relativePosition * getPrevBoneMatrix(input.indexes.w)) * skinWeights.w;
		previousTransformedPosition = prevPosition;
	};
}

{
	@param var texture:Sampler2D;
	var calculatedUV:Vec2;
	var specColor:Vec3;
	function fragment() {
		specColor *= texture.get(calculatedUV).rgb;
	};
}

{
	@:extends h3d.shader.ShadowSampling;
	@const var enable:Bool;
	@const(2) var SAMPLING_MODE:Int;
	@param var shadowPower:Float;
	@param var pcfScale:Float;
	@param var shadowMap:Sampler2D;
	@param var shadowViewProj:Mat4;
	@param var shadowBias:Float;
	var transformedPosition:Vec3;
	var shadow:Float;
	function fragment() {
		if (enable) {
			var shadowPos = spotShadowPos(transformedPosition, shadowViewProj);
			shadow = sampleShadow(shadowMap, shadowPos.xy, shadowPos.z.saturate(), shadowBias, pcfScale, shadowPower, transformedPosition, SAMPLING_MODE);
		};
	};
}

{
	@input var input:{ var uv : Vec2};
	@const var additive:Bool;
	@const var killAlpha:Bool;
	@const var specularAlpha:Bool;
	@range(0, 1) @param var killAlphaThreshold:Float;
	@param var texture:Sampler2D;
	var calculatedUV:Vec2;
	var pixelColor:Vec4;
	var specColor:Vec3;
	function vertex() {
		calculatedUV = input.uv;
	};
	function fragment() {
		var c = texture.get(calculatedUV);
		if (killAlpha && c.a - killAlphaThreshold < 0) discard;
		if (additive) pixelColor += c else pixelColor *= c;
		if (specularAlpha) specColor *= c.aaa;
	};
}

{
	@input var input:{ var uv2 : Vec2};
	@const var additive:Bool;
	@const var killAlpha:Bool;
	@param var killAlphaThreshold:Float;
	@param var texture:Sampler2D;
	var calculatedUV2:Vec2;
	var pixelColor:Vec4;
	function vertex() {
		calculatedUV2 = input.uv2;
	};
	function fragment() {
		var c = texture.get(calculatedUV2);
		if (killAlpha && c.a - killAlphaThreshold < 0) discard;
		if (additive) pixelColor += c else pixelColor *= c;
	};
}

new.haxe_doc:
Creates the shader.
		@param frameDivision The number of frames on each axis of the texture.
		@param totalFrames The number of frames, or `-1` for all the cells.
		@param speed The number of frames per second.

m.e:
{
	var calculatedUV:Vec2;
	@global var global:{ var time : Float};
	@param var speed:Float;
	@param var frameDivision:Float;
	@param var totalFrames:Float;
	@param var startTime:Float;
	@const var loop:Bool;
	function vertex() {
		var frame = float(int((global.time - startTime) * speed));
		if (loop) frame %= totalFrames else frame = min(frame, totalFrames - 1);
		var delta = vec2(1. / frameDivision, 1. / frameDivision) * vec2(frame % frameDivision, float(int(frame / frameDivision)));
		calculatedUV += delta;
	};
}

{
	@param var uvDelta:Vec2;
	@param var uvScale:Vec2;
	var calculatedUV:Vec2;
	function vertex() {
		calculatedUV = calculatedUV * uvScale + uvDelta;
	};
}

{
	@global var global:{ var time : Float};
	@param var uvSpeed:Vec2;
	var calculatedUV:Vec2;
	function vertex() {
		calculatedUV += uvSpeed * global.time;
	};
}

{
	@input var input:{ var color : Vec3};
	var pixelColor:Vec4;
	@const var additive:Bool;
	function fragment() {
		if (additive) pixelColor.rgb += input.color else pixelColor.rgb *= input.color;
	};
}

{
	@input var input:{ var color : Vec4};
	var pixelColor:Vec4;
	@const var additive:Bool;
	function fragment() {
		if (additive) pixelColor += input.color else pixelColor *= input.color;
	};
}

{
	@global var camera:{ var position : Vec3; var view : Mat4};
	@param var areaScale:Float = 300;
	var transformedPosition:Vec3;
	@flat var flatPos:Vec3;
	var pixelColor:Vec4;
	function __init__vertex() {
		flatPos = transformedPosition;
	};
	function ramp0(ft:Float):Vec3 {
		var t = clamp(ft, 0.0, 1.0);
		t *= 4.;
		return clamp(vec3(min(t - 1.5, 4.5 - t), min(t - 0.5, 3.5 - t), min(t + 0.5, 2.5 - t)), 0.0, 1.0);
	};
	function fragment() {
		var v0 = vertexAt(flatPos, 0);
		var v1 = vertexAt(flatPos, 1);
		var v2 = vertexAt(flatPos, 2);
		var viewPos = vec4(v0, 1) * camera.view;
		var area = cross(v1 - v0, v2 - v0).length() * 0.5;
		var density = viewPos.z / (sqrt(area) * areaScale);
		pixelColor.rgb = ramp0(saturate(density));
		var minBary = min(barycentrics.x, min(barycentrics.y, barycentrics.z));
		var wire = smoothstep(0.0, fwidth(minBary) * 1.0, minBary);
		pixelColor.rgb = mix(pixelColor.rgb, vec3(0), wire * 0.25);
	};
}

{
	@:import BaseMesh;
	@global var depthMap:Channel;
	@param var scale:Vec2;
	@param var normal:Vec3;
	@param var tangent:Vec3;
	@const var isCentered:Bool = true;
	var calculatedUV:Vec2;
	var transformedTangent:Vec4;
	function __init__vertex() {
		transformedNormal = (normal * global.modelView.mat3()).normalize();
		transformedTangent = vec4((tangent * global.modelView.mat3()).normalize(), 1.);
	};
	function fragment() {
		var matrix = camera.inverseViewProj * global.modelViewInverse;
		var screenPos = projectedPosition.xy / projectedPosition.w;
		var ruv = vec4(screenPos, depthMap.get(screenToUv(screenPos)), 1);
		var wpos = ruv * matrix;
		var ppos = ruv * camera.inverseViewProj;
		pixelTransformedPosition = ppos.xyz / ppos.w;
		calculatedUV = scale * (wpos.xy / wpos.w);
		if (isCentered) calculatedUV += 0.5;
		if (min(min(calculatedUV.x, calculatedUV.y), min(1 - calculatedUV.x, 1 - calculatedUV.y)) < 0) discard;
	};
}

{
	var textureColor:Vec4;
	function fragment() {
		textureColor.rgb = vec3(1.0);
	};
}

{
	@:import h3d.shader.BaseMesh;
	@param var zMin:Float;
	@param var zMax:Float;
	function vertex() {
		var z = projectedPosition.z / projectedPosition.w;
		z -= min(z - zMin, 0.) * 1e8;
		z += min(zMax - z, 0.) * 1e8;
		projectedPosition.z = z * projectedPosition.w;
		pixelColor.rgb = z.xxx;
	};
}

{
	var normal:Vec3;
	var pixelColor:Vec4;
	function fragment() {
		var isSky = normal.dot(normal) <= 0;
		if (isSky) pixelColor.a = 0;
	};
}

{
	var pixelColor:Vec4;
	function fragment() {
		pixelColor.rgb *= pixelColor.a;
	};
}

{
	function getAnisotropicRoughness(roughness:Float, anisotropy:Float):Vec2 {
		var at = max(roughness * (1.0 + anisotropy), 0.001);
		var ab = max(roughness * (1.0 - anisotropy), 0.001);
		return vec2(at, ab);
	};
	function smithGGXCorrelatedAnisotropic(at:Float, ab:Float, TdV:Float, BdV:Float, TdL:Float, BdL:Float, NdV:Float, NdL:Float):Float {
		var lambdaV = NdL * length(vec3(at * TdV, ab * BdV, NdV));
		var lambdaL = NdV * length(vec3(at * TdL, ab * BdL, NdL));
		var v = 0.5 / (lambdaV + lambdaL);
		return saturate(v);
	};
	function normalDistributionGGXAnisotropic(at:Float, ab:Float, NdH:Float, TdH:Float, BdH:Float, roughness:Float, anisotropy:Float):Float {
		var a2 = at * ab;
		var v = vec3(ab * TdH, at * BdH, a2 * NdH);
		var v2 = dot(v, v);
		var w2 = a2 / v2;
		return a2 * w2 * w2 * (1.0 / PI);
	};
	function normalDistributionGGX(NdH:Float, roughness:Float):Float {
		var alpha = roughness * roughness;
		var alpha2 = alpha * alpha;
		var denom = NdH * NdH * (alpha2 - 1.) + 1;
		return alpha2 / (PI * denom * denom);
	};
	function geometrySchlickGGX(NdV:Float, NdL:Float, roughness:Float):Float {
		var k = (roughness + 1);
		k *= k;
		k *= 0.125;
		return (1 / (NdV * (1 - k) + k)) * (1 / (NdL * (1 - k) + k)) * 0.25;
	};
	function fresnelSchlick(VdH:Float, F0:Vec3):Vec3 {
		return F0 + (1. - F0) * exp2((-5.55473 * VdH - 6.98316) * VdH);
	};
}

{
	@global var camera:{ var view : Mat4; var invProj : Mat4; @const
	var reverseDepth : Bool};
	@param var lightInfos:Buffer<Vec4,4096>;
	@param var clusterData:RWBuffer<Int>;
	var POINT_LIGHT_STRIDE:Int = 2;
	var SPOT_LIGHT_STRIDE:Int = 3;
	var CAPSULE_LIGHT_STRIDE:Int = 3;
	var RECT_LIGHT_STRIDE:Int = 6;
	var CLUSTER_X:Int = 16;
	var CLUSTER_Y:Int = 9;
	var CLUSTER_Z:Int = 24;
	var CLUSTER_STRIDE:Int = 128;
	@param var pointLightOffset:Int;
	@param var pointStart:Int;
	@param var pointEnd:Int;
	@param var spotLightOffset:Int;
	@param var spotStart:Int;
	@param var spotEnd:Int;
	@param var capsuleLightOffset:Int;
	@param var capsuleStart:Int;
	@param var capsuleEnd:Int;
	@param var rectLightOffset:Int;
	@param var rectStart:Int;
	@param var rectEnd:Int;
	@param var clusterNear:Float;
	@param var clusterFarOverNear:Float;
	@param var clusterLastSliceFar:Float;
	@const var USE_HZB:Bool;
	@param var hzb:Sampler2D;
	@param var hzbSize:Vec2;
	@const var USE_OCCLUSION:Bool;
	@param var lightVisible:StorageBuffer<Int>;
	@param var spotSlot:Int;
	@param var capsuleSlot:Int;
	@param var rectSlot:Int;
	var aabbMin:Vec3;
	var aabbMax:Vec3;
	var count:Int;
	var typeCount:Int;
	var base:Int;
	function unproject(ndc:Vec2, z:Float):Vec3 {
		var p = vec4(ndc, z, 1.0) * camera.invProj;
		return p.xyz / p.w;
	};
	function rayAtDepth(ndc:Vec2, z:Float):Vec3 {
		var a = unproject(ndc, 0.0);
		var b = unproject(ndc, 0.5);
		return mix(a, b, (z - a.z) / (b.z - a.z));
	};
	function addCorner(ndc:Vec2, z0:Float, z1:Float) {
		var p0 = rayAtDepth(ndc, z0);
		var p1 = rayAtDepth(ndc, z1);
		aabbMin = min(aabbMin, min(p0, p1));
		aabbMax = max(aabbMax, max(p0, p1));
	};
	function sphereTest(center:Vec3, radius:Float):Bool {
		var d = max(aabbMin - center, vec3(0.0)) + max(center - aabbMax, vec3(0.0));
		return dot(d, d) <= radius * radius;
	};
	function toView(p:Vec3):Vec3 {
		return (vec4(p, 1.0) * camera.view).xyz;
	};
	function dirToView(d:Vec3):Vec3 {
		return (vec4(d, 0.0) * camera.view).xyz;
	};
	function rangeFromInv4(invRange4:Float):Float {
		return pow(invRange4, -0.25) * 1.001;
	};
	function pushLight(index:Int) {
		if (count < CLUSTER_STRIDE - 1) {
			clusterData[base + 1 + count] = index;
			count += 1;
			typeCount += 1;
		};
	};
	function tileFarDepth(tx:Int, ty:Int):Float {
		var tileSize = hzbSize / vec2(float(CLUSTER_X), float(CLUSTER_Y));
		var lod = max(0.0, floor(log2(min(tileSize.x, tileSize.y))));
		var texel = exp2(lod);
		var mipSize = max(vec2(1.0), floor(hzbSize / texel));
		var pixelMin = vec2(float(tx), float(CLUSTER_Y - 1 - ty)) * tileSize;
		var texelMin = ivec2(floor(pixelMin / texel));
		var texelMax = ivec2(min(ceil((pixelMin + tileSize) / texel), mipSize) - 1.0);
		var depth = camera.reverseDepth ? 1.0 : 0.0;
		for (y  in  texelMin.y ... texelMax.y + 1) for (x  in  texelMin.x ... texelMax.x + 1) {
			var d = hzb.fetchLod(ivec2(x, y), int(lod)).x;
			depth = camera.reverseDepth ? min(depth, d) : max(depth, d);
		};
		var p = vec4(0.0, 0.0, depth, 1.0) * camera.invProj;
		return p.z / p.w;
	};
	function main() {
		setLayout(64, 1, 1);
		var id = computeVar.globalInvocation.x;
		if (id >= CLUSTER_X * CLUSTER_Y * CLUSTER_Z) return;
		var tx = id % CLUSTER_X;
		var ty = (id / CLUSTER_X) % CLUSTER_Y;
		var tz = id / (CLUSTER_X * CLUSTER_Y);
		base = id * CLUSTER_STRIDE;
		var ndcMin = vec2(float(tx) / float(CLUSTER_X), float(ty) / float(CLUSTER_Y)) * 2.0 - 1.0;
		var ndcMax = vec2(float(tx + 1) / float(CLUSTER_X), float(ty + 1) / float(CLUSTER_Y)) * 2.0 - 1.0;
