{
	@param var texture:Sampler2D;
	@param var color:Vec3;
	function fragment() {
		var outval = texture.get(calculatedUV).rgb;
		pixelColor.a = outval.r > 0.1 && outval.r < 0.5 ? 1.0 : 0.0;
		pixelColor.rgb = color;
	};
}

{
	@param var noise:Sampler2D;
	@perInstance @param var noiseScale:Vec2 = vec2(1.0, 1.0);
	@perInstance @param var noiseOffset:Vec2 = vec2(0.0, 0.0);
	@perInstance @param var dissolveWidth:Float = 0.5;
	@param var alphaThreshold:Float = 0.1;
	@perInstance @param var dissolveAmmount:Float = 0.5;
	@perInstance @param var colorBurn:Vec4;
	var pixelColor:Vec4;
	var calculatedUV:Vec2;
	function fragment() {
		var col:Vec4 = pixelColor;
		var noiseUV = mod((calculatedUV + noiseOffset) * noiseScale, vec2(1.0, 1.0));
		var dissolve = noise.get(noiseUV).r;
		var dissolveAmmountRemmaped = (1.0 - dissolveAmmount * 2.0);
		dissolve += dissolveAmmountRemmaped;
		dissolve = (dissolve - 0.5) * 10.0;
		dissolve = clamp(dissolve, 0.0, 1.0);
		var edge = dissolve - (1.0 - step(dissolve, dissolveWidth));
		var edgeColor = colorBurn * edge;
		col.rgb *= dissolve;
		col.rgb += edgeColor.rgb;
		col.rgb = clamp(col.rgb, vec3(0.0), vec3(1.0));
		col.a = dissolve;
		if (col.a < alphaThreshold) {
			discard;
		};
		pixelColor = col;
	};
}

{
	var pixelColor:Vec4;
	var calculatedUV:Vec2;
	function fragment() {
		var uv = calculatedUV;
		pixelColor.rgb = vec3(uv.x % 1.0, uv.y, 0.0);
	};
}

{
	@const var USE_ALPHA:Bool;
	@param var gradient:Sampler2D;
	var pixelColor:Vec4;
	function fragment() {
		var t = USE_ALPHA ? pixelColor.a : dot(pixelColor.rgb * pixelColor.rgb, vec3(0.2126, 0.7152, 0.0722));
		var uv2 = vec2(t, 0.5);
		var size = gradient.size();
		uv2 = clamp(uv2, 0.5 / size, (size - vec2(0.5)) / size);
		pixelColor.rgb = gradient.get(uv2).rgb;
	};
}

{
	var pixelColor:Vec4;
	@global var global:{ var time : Float; var pixelSize : Vec2; @perObject
	var modelView : Mat4; @perObject
	var modelViewInverse : Mat4};
	@param var heightRange:Vec2 = vec2(0.0, 1.0);
	@param var direction:Vec3 = vec3(0.0, 0.0, 1.0);
	@param var gradient:Sampler2D;
	@param var alphaMult:Float = 1.0;
	@const var useWorldPosition:Bool = false;
	var transformedPosition:Vec3;
	function fragment() {
		var position = transformedPosition;
		if (!useWorldPosition) {
			transformedPosition -= vec3(global.modelView[0].w, global.modelView[1].w, global.modelView[2].w);
		};
		var d = normalize(direction);
		var position = transformedPosition;
		var heightRemaped = clamp(dot(position, d), heightRange.x, heightRange.y);
		var blend = (heightRemaped - heightRange.x) / abs(heightRange.y - heightRange.x);
		var color = gradient.get(vec2(blend, 0.5));
		pixelColor.rgb = mix(pixelColor.rgb, color.rgb, color.a * alphaMult);
	};
}

{
	@:import hrt.shader.BaseEmitter;
	@param var fadeInLife:Float = 0.1;
	@param var fadeOutLife:Float = 0.1;
	@param @range(0.01, 10) var power:Float = 1.0;
	function fragment() {
		var t = particleLife / particleLifeTime;
		var fadeIn = t / max(0.0001, fadeInLife);
		var fadeOut = (1.0 - t) / max(0.0001, fadeOutLife);
		pixelColor.a *= pow(saturate(min(fadeIn, fadeOut)), power);
	};
}

{
	@:import hrt.shader.BaseEmitter;
	@param var gradient:Sampler2D;
	function fragment() {
		pixelColor.rgb *= gradient.get(vec2(particleLife / particleLifeTime, 0.5)).rgb;
	};
}

{
	@:import hrt.shader.BaseEmitter;
	@param var gradient:Sampler2D;
	function fragment() {
		pixelColor.rgb *= gradient.get(vec2(particleRandom, 0.5)).rgb;
	};
}

{
	@:import hrt.shader.BaseEmitter;
	@const @param var axis:hrt.shader.ParticleRandomMesh.ParticleRandomMeshAxis = PosX;
	@range(1, 32) @param var cellCount:Int = 4;
	@range(0, 10) @param var cellSize:Float = 1.0;
	@const @param var recenter:Bool = true;
	function vertex() {
		var s = (axis == NegX || axis == NegY || axis == NegZ) ? -1.0 : 1.0;
		var dir = axis.toInt() < PosY.toInt() ? vec3(s, 0.0, 0.0) : (axis.toInt() < PosZ.toInt() ? vec3(0.0, s, 0.0) : vec3(0.0, 0.0, s));
		var count = max(float(cellCount), 1.0);
		var cell = min(floor(particleRandom * count), count - 1.0);
		var pos = relativePosition * meshToModel.mat3x4();
		var start = cell * cellSize;
		var local = dot(pos, dir) - start;
		if (local < 0.0 || local > cellSize) pos = vec3(0.0) else pos -= dir * (recenter ? start + cellSize * 0.5 : start);
		relativePosition = pos * modelToMesh.mat3x4();
	};
}

{
	@const var MULTIPLY:Bool;
	@perInstance @param var color:Vec4;
	@param var mask:Sampler2D;
	@perInstance @param var UVOffset:Vec2;
	@perInstance @param var UVScale:Vec2 = vec2(1.0, 1.0);
	@perInstance @param var alpha:Float = 1.0;
	var pixelColor:Vec4;
	var calculatedUV:Vec2;
	function fragment() {
		var texColor = mask.get(mod((calculatedUV + UVOffset) * UVScale, vec2(1.0, 1.0)));
		var maskAlpha = texColor.r;
		if (MULTIPLY) {
			pixelColor.rgb = mix(pixelColor.rgb, pixelColor.rgb * color.rgb, maskAlpha * alpha);
		} else {
			pixelColor.rgb = mix(pixelColor.rgb, color.rgb, maskAlpha * alpha);
		};
	};
}

{
	var pixelColor:Vec4;
	@param var shapeSDF:Sampler2D;
	@param var trailTexture:Sampler2D;
	@param var scaleX:Float = 1.0;
	@param var scaleY:Float = 1.0;
	@param var scaleTime:Float = 1.0;
	@param var timeOffset:Float = 0.0;
	@const var correctTextureNormals:Bool = false;
	@param var numTrails:Float = 3;
	@const var useTimeTexture:Bool = false;
	@param var timeTexture:Sampler2D;
	@const var debugShowShape:Bool = false;
	@global var global:{ var time : Float};
	var calculatedUV:Vec2;
	function dist(uv:Vec2):Float {
		var c = shapeSDF.get(uv);
		return max(min(c.r, c.b), min(max(c.r, c.g), c.b)) - 0.5;
	};
	function fragment() {
		var uv = calculatedUV;
		var sdf = dist(uv);
		var uvSurface = calculatedUV - vec2(0.5);
		if (correctTextureNormals) {
			var dd = vec3(1.0 / shapeSDF.size().x, 1.0 / shapeSDF.size().y, 0.0);
			var norm = normalize(vec2(dist(uv + dd.xz) - dist(uv - dd.xz), dist(uv + dd.zy) - dist(uv - dd.zy)));
			uvSurface -= norm * sdf * 0.25;
		};
		var g = useTimeTexture ? timeTexture.get(uv).r : atan(uvSurface.y, uvSurface.x) / (2 * 3.1415) + 0.5;
		var trueTime = global.time * scaleTime + timeOffset;
		var t = g - mod(trueTime, 1.0);
		t = 1.0 - mod(t, 1.0);
		t = mod(t * numTrails, 1.0);
		var uvLocal = vec2(1.0 - t, ((scaleY - sdf) / scaleY) / 2.0);
		uvLocal.x = 1.0 - (1.0 - uvLocal.x) / scaleX;
		uvLocal = clamp(uvLocal, vec2(0.01), vec2(1.0));
		var trail = trailTexture.get(uvLocal);
		if (debugShowShape) {
			pixelColor = mix(trail, vec4(1.0), 1.0 - smoothstep(0.0, 0.01, abs(sdf)));
		} else {
			pixelColor = trail;
		};
	};
}

{
	var calculatedUV:Vec2;
	var pixelColor:Vec4;
	@param var sampler:Sampler2D;
	@param var pxRange:Float;
	@param var bgColor:Vec4;
	@param var fgColor:Vec4;
	function screenPxRange():Float {
		var unitRange = vec2(pxRange) / vec2(sampler.size());
		var screenTexSize = vec2(1.0) / fwidth(calculatedUV);
		return max(0.5 * dot(unitRange, screenTexSize), 1.0);
	};
	function fragment() {
		var distance:Float = sampler.get(calculatedUV).r;
		var sceenPxDistance = screenPxRange() * (distance - 0.5);
		var opacity:Float = clamp(sceenPxDistance + 0.5, 0.0, 1.0);
		pixelColor = mix(bgColor, fgColor, opacity);
		pixelColor.a *= opacity;
	};
}

{
	@global var global:{ var time : Float};
	@input var input:{ var position : Vec3; var normal : Vec3; var color : Vec3};
	@param var axis:Vec3 = vec3(0.0, 1.0, 0.0);
	@param var speed:Float = 0.5;
	@param var length:Float = 1.0;
	@param var scale:Float = 1.0;
	@param var fmSpeed:Float = 0.47;
	@param var fmAmplitude:Float = 0.25;
	@param var randomScale:Float = 0.0;
	@param var randomSpeed:Float = 0.12;
	var random:Float;
	function __init__() {
		random = 0.5;
	};
	var relativePosition:Vec3;
	function vertex() {
		var tau = 6.28318530718;
		var rScale = random != 0.5 ? exp((random - 0.5) * randomScale) : 0.5;
		var rSpeed = random != 0.5 ? exp(((random * 1.7548912 % 1.0) - 0.5) * randomSpeed) : 0.5;
		var xScale = 1.0 / max(length, 0.001);
		var carrierSpeed = global.time * rSpeed * speed * tau;
		var dispScale = sin(carrierSpeed + relativePosition.x * xScale + random + sin(carrierSpeed * fmSpeed + random) * fmAmplitude) * input.color.r * scale * rScale;
		relativePosition += dispScale * axis;
	};
}

{
	@param @range(0, 360) var rotate = 0.0;
	@param var rotateCenter:Vec2 = vec2(0.5, 0.5);
	@const var flipX:Bool;
	@const var flipY:Bool;
	var calculatedUV:Vec2;
	function fragment() {
		var a = rotate * 2 * 3.14159265 / 360.0;
		var m = mat2(vec2(cos(a), -sin(a)), vec2(sin(a), cos(a)));
		var uv = calculatedUV;
		if (flipX) uv.x = 1 - uv.x;
		if (flipY) uv.y = 1 - uv.y;
		calculatedUV = (uv - rotateCenter) * m + rotateCenter;
	};
}

{
	@:import hrt.shader.BaseEmitter;
	@const var colorMult:Bool;
	@const var destAlpha:Bool = true;
	@param var gradient:Sampler2D;
	function fragment() {
		var s = gradient.size();
		var sample = gradient.get(vec2(saturate(particleLife / particleLifeTime)) * (s - vec2(1.0)) / (s));
		if (colorMult) {
			pixelColor.rgb *= sample.rgb;
		} else {
			pixelColor.rgb = sample.rgb;
		};
		if (destAlpha) {
			pixelColor.a *= sample.a;
		};
	};
}

{
	var pixelColor:Vec4;
	var calculatedUV:Vec2;
	@param var texture:Sampler2D;
	function fragment() {
		var tex = texture.get(calculatedUV);
		pixelColor.rgba *= tex.rgba;
	};
}

{
	@param var power:Float;
	var emissive:Float;
	function fragment() {
		emissive = emissive * power;
	};
}

{
	@const var USE_SOURCE_UV:Bool = false;
	@param var amount:Float = 1.0;
	@param var gradient:Sampler2D;
	@input var input:{ var uv : Vec2};
	var calculatedUV:Vec2;
	var pixelColor:Vec4;
	function __init__():Void {
		calculatedUV = input.uv;
	};
	function fragment() {
		var gradientVal = gradient.get(USE_SOURCE_UV ? input.uv : calculatedUV);
		pixelColor.rgb = mix(pixelColor.rgb, gradientVal.rgb, amount);
	};
}

