{
	@input var input:{ var uv : Vec2};
	var pixelColor:Vec4;
	function fragment() {
		var cb = floor(mod(input.uv * 10.0, vec2(2.0)));
		var check = mod(cb.x + cb.y, 2.0);
		var color = check >= 1.0 ? vec3(0.22) : vec3(0.44);
		pixelColor.rgb = mix(color, pixelColor.rgb, pixelColor.a);
	};
}

{
	@param var compressedTex:Sampler2D;
	@param var uncompressedTex:Sampler2D;
	@param var textureCube:SamplerCube;
	@param var textureArray:Sampler2DArray;
	@param var layer:Float;
	@param var mipLod:Float;
	@param var exposure:Float;
	@param var comparisonFactor:Float;
	@const var channels:Int;
	@const var isCube:Bool;
	@const var isArray:Bool;
	var pixelColor:Vec4;
	var calculatedUV:Vec2;
	var transformedNormal:Vec3;
	function fragment() {
		if (isCube) pixelColor = textureCube.getLod(transformedNormal, mipLod) else if (isArray) pixelColor = textureArray.getLod(vec3(calculatedUV, layer), mipLod) else {
			if (calculatedUV.x > comparisonFactor) pixelColor = uncompressedTex.getLod(calculatedUV, mipLod) else pixelColor = compressedTex.getLod(calculatedUV, mipLod);
		};
		pixelColor.rgb *= pow(2, exposure);
		switch (channels) {
			case 0, 15:
			case 1:
				pixelColor = vec4(pixelColor.rrr, 1.);			
			case 2:
				pixelColor = vec4(pixelColor.ggg, 1.);			
			case 4:
				pixelColor = vec4(pixelColor.bbb, 1.);			
			case 8:
				pixelColor = vec4(pixelColor.aaa, 1.);			
			default:
				if (channels & 1 == 0) pixelColor.r = 0;
				if (channels & 2 == 0) pixelColor.g = 0;
				if (channels & 4 == 0) pixelColor.b = 0;
				if (channels & 8 == 0) pixelColor.a = 1;			
		};
	};
}

{
	@param var comparisonFactor:Float;
	function fragment() {
		if (calculatedUV.x > comparisonFactor) pixelColor = texture.get(calculatedUV) else {
			pixelColor.rgb = vec3(1.0);
			var sample = texture.get(calculatedUV);
			var sd = median(sample.r, sample.g, sample.b);
			var screenPxDistance = screenPxRange(calculatedUV) * (sd - 0.5);
			pixelColor.a = clamp(screenPxDistance + 0.5, 0.0, 1.0);
		};
	};
}

class.haxe_doc:
A simple socket-based local communication channel (plaintext and unsafe),
	aim at communicate between 2 programs (e.g. Hide and a HL game).

	Usage in game (see also hrt.impl.RemoteTools):
	```haxe
	var rcmd = new hrt.impl.RemoteConsole();
	// rcmd.log = (msg) -> logToUI(msg);
	// rcmd.logError = (msg) -> logErrorToUI(msg);
	rcmd.connect();
	rcmd.sendCommand("log", "Hello!", function(r) {});
	```

