		sum += texture(source, calculatedUV - halfPixel.xy).rgb;
		sum += texture(source, calculatedUV + vec2(halfPixel.x, -halfPixel.y)).rgb;
		sum += texture(source, calculatedUV - vec2(halfPixel.x, -halfPixel.y)).rgb;
		pixelColor.rgb = max(sum / 8.0, 0.0);
	};
