	function GGX_Aniso_NDF(alpha_t:Float, alpha_b:Float, ToH:Float, BoH:Float, NoH:Float):Float {
		var invpi = 1.0 / PI;
		var v = vec3(alpha_b * ToH, alpha_t * BoH, alpha_t * alpha_b * NoH);
		var v2 = dot(v, v);
		var a2 = alpha_t * alpha_b;
		var w2 = a2 / v2;
		return (a2 * w2 * w2 * invpi);
