	@sginput(2.0) var sharpness:Float;
	@sginput(1.0) var tiling:Vec3;
	@sginput(0.0) var offset:Vec3;
	@sgconst var MODE:Int = 0;
	@sgoutput var weight:Vec3;
	@sgoutput var uvX:Vec2;
	@sgoutput var uvY:Vec2;
	@sgoutput var uvZ:Vec2;
	@input var input:{ var normal : Vec3};
	@global var global:{ @perObject
	var modelViewInverse : Mat4; @perObject
	var modelView : Mat4};
	var transformedNormal:Vec3;
	var transformedPosition:Vec3;
	var relativePosition:Vec3;
	function fragment() {
		var normal = MODE == 0 ? transformedNormal : input.normal;
		var position = MODE == 1 ? relativePosition.xyz : transformedPosition.xyz;
		if (MODE == 2) {
			var scaleRot = global.modelView.mat3();
			var rot = mat3(normalize(vec3(scaleRot[0].x, scaleRot[1].x, scaleRot[2].x)), normalize(vec3(scaleRot[0].y, scaleRot[1].y, scaleRot[2].y)), normalize(vec3(scaleRot[0].z, scaleRot[1].z, scaleRot[2].z)));
			position = position * rot;
		};
		weight = pow(abs(normal), vec3(sharpness));
		weight = weight / (weight.x + weight.y + weight.z);
		var tiledAndOffsetPos = position * tiling + offset;
		uvX = tiledAndOffsetPos.zy;
		uvY = tiledAndOffsetPos.xz;
		uvZ = tiledAndOffsetPos.xy;
	};
}

{
	@sginput var texture:Sampler2D;
	@sginput var weight:Vec3;
	@sginput var uvX:Vec2;
	@sginput var uvY:Vec2;
	@sginput var uvZ:Vec2;
	@sgoutput var RGBA:Vec4;
	function fragment() {
		RGBA = texture.get(uvX) * weight.x + texture.get(uvY) * weight.y + texture.get(uvZ) * weight.z;
	};
}

{
	@sginput("calculatedUV") var uv:Vec2;
	@sginput(1.0) var uSpeed:Float;
	@sginput(1.0) var vSpeed:Float;
	@sginput("global.time") var time:Float;
	@sgoutput var output:Vec2;
	function fragment() {
		output = uv + vec2(uSpeed * time, vSpeed * time);
	};
}

{
	@sginput(0.0) var a:Vec4;
	@sgoutput var output:Vec3;
	function fragment() {
		output = unpackNormal(a);
	};
}

{
	@sginput var uv:Vec2;
	@sgoutput var output:Vec2;
	function fragment() {
		output = uvToScreen(uv);
	};
}

{
	@sginput(0.0) var x:Float;
	@sginput(0.0) var y:Float;
	@sgoutput var output:Vec2;
	function fragment() {
		output = vec2(x, y);
	};
}

{
	@sginput(0.0) var x:Float;
	@sginput(0.0) var y:Float;
	@sginput(0.0) var z:Float;
	@sgoutput var output:Vec3;
	function fragment() {
		output = vec3(x, y, z);
	};
}

{
	@sginput(0.0) var x:Float;
	@sginput(0.0) var y:Float;
	@sginput(0.0) var z:Float;
	@sginput(0.0) var w:Float;
	@sgoutput var output:Vec4;
	function fragment() {
		output = vec4(x, y, z, w);
	};
}

{
	@sginput var input:Vec3;
	@sgoutput var output:Vec3;
	@sgconst var translate:Int;
	@global var camera:{ var view : Mat4};
	function fragment() {
		if (translate == 1) output = input * camera.view.mat3x4() else output = input * camera.view.mat3();
	};
}

{
	@sginput var input:Vec3;
	@sgoutput var output:Vec3;
	@sgconst var translate:Int;
	@global var global:{ @perObject
	var modelViewInverse : Mat4};
	function fragment() {
		if (translate == 1) output = input * global.modelViewInverse.mat3x4() else output = input * global.modelViewInverse.mat3();
	};
}

{
	@sginput var input:Vec3;
	@sgoutput var output:Vec3;
	@global var camera:{ var viewProj : Mat4};
	function fragment() {
		var result = vec4(input, 1.0) * camera.viewProj;
		output = result.xyz / result.w;
	};
}

{
	@sginput var direction:Vec3;
	@sgoutput var output:Vec3;
	@global var global:{ @perObject
	var modelViewInverse : Mat4};
	@input var input:{ var normal : Vec3; var tangent : Vec3};
	var transformedNormal:Vec3;
	function fragment() {
		var directionObj = direction * global.modelViewInverse.mat3();
		var tangent = input.tangent;
		var signTangent = tangent.dot(tangent) > 0.5 ? -1. : 1.;
		var normal = input.normal;
		var bitangent = cross(normal, tangent) * signTangent;
		output = vec3(dot(directionObj, tangent), dot(directionObj, bitangent), dot(directionObj, normal));
	};
}

{
	@param var tex:Sampler2D;
	@param var seed:Float;
	@param var scale:Float;
	function random(inVector:Vec2):Float {
		return fract(sin(dot(inVector.xy, vec2(12.9898, 78.233))) * 43758.5453123);
	};
	function noise(inVector:Vec2):Float {
		var i = floor(inVector);
		var f = fract(inVector);
		var a = random(i);
		var b = random(i + vec2(1.0, 0.0));
		var c = random(i + vec2(0.0, 1.0));
		var d = random(i + vec2(1.0, 1.0));
		var u = f * f * (3.0 - 2.0 * f);
		return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
	};
	function fragment() {
		pixelColor = vec4(vec3(noise((uvToScreen(calculatedUV) + seed) * scale)), 1.);
	};
}

{
	@param var tex1:Sampler2D;
	@param var tex2:Sampler2D;
	function fragment() {
		pixelColor = tex1.get(calculatedUV) * tex2.get(calculatedUV);
	};
}

{
	@param var r:Sampler2D;
	@param var g:Sampler2D;
	@param var b:Sampler2D;
	@param var a:Sampler2D;
	function fragment() {
		pixelColor.r = r.get(calculatedUV).r;
		pixelColor.g = g.get(calculatedUV).r;
		pixelColor.b = b.get(calculatedUV).r;
		pixelColor.a = a.get(calculatedUV).r;
	};
}

{
	@param var tex:Sampler2D;
	@const var channels:Int;
	function fragment() {
		switch (channels) {
			case 0:
				pixelColor = vec4(tex.get(calculatedUV).rrr, 1.);			
			case 1:
				pixelColor = vec4(tex.get(calculatedUV).ggg, 1.);			
			case 2:
				pixelColor = vec4(tex.get(calculatedUV).bbb, 1.);			
			case 3:
				pixelColor = vec4(tex.get(calculatedUV).aaa, 1.);			
			default:
				pixelColor = vec4(0, 0, 0, 0);			
		};
	};
}

{
	@param var tex:Sampler2D;
	@param var seed:Float;
	function random(inVector:Vec2):Float {
		return fract(sin(dot(inVector.xy, vec2(12.9898, 78.233))) * 43758.5453123);
	};
	function fragment() {
		pixelColor = vec4(vec3(random(uvToScreen(calculatedUV) + seed)), 1.);
	};
}

{
	@global var camera:{ @var
	var dir : Vec3};
	@global var global:{ @perObject
	var modelView : Mat4};
	var transformedPosition:Vec3;
	var modelView:Mat4;
	var pixelColor:Vec4;
	function fragment() {
		var center = vec3(global.modelView[0].w, global.modelView[1].w, global.modelView[2].w);
		var camDir = camera.dir * -1;
		var dot = dot(camDir, (center - transformedPosition).normalize());
		pixelColor.a = ceil(clamp(dot, -0.15, 1) + 0.15);
	};
}

{
	@global var camera:{ @var
	var dir : Vec3};
	@global var global:{ @perObject
	var modelView : Mat4};
	var transformedPosition:Vec3;
	var modelView:Mat4;
	var pixelColor:Vec4;
	function fragment() {
		var center = vec3(global.modelView[0].w, global.modelView[1].w, global.modelView[2].w);
		var camDir = camera.dir * -1;
		var dot = dot(camDir, (center - transformedPosition).normalize());
		pixelColor.a = dot < 0.2 && dot > -0.2 ? 1 : 0;
	};
}

{
	@global var camera:{ var position : Vec3};
	@param var color:Vec3;
	@param var lineWidth:Float;
	@param var lineSpacing:Float;
	var transformedPosition:Vec3;
	var pixelColor:Vec4;
	function pristineGrid(position:Vec2, lineWidth:Vec2, idx:Int):Float {
		var f = length(abs(camera.position - transformedPosition)) / pow(100, float(idx));
		lineWidth = min(lineWidth, saturate(lineWidth * f));
		var posDDXY = vec4(dFdx(position), dFdy(position));
		var posDeriv = vec2(length(posDDXY.xz), length(posDDXY.yw));
		var invertLine = length(lineWidth) > 0.5;
		var targetWidth = invertLine ? 1.0 - lineWidth : lineWidth;
		var drawWidth = clamp(targetWidth, posDeriv, vec2(0.5, 0.5));
		var lineAA = max(posDeriv, 0.000001) * 1.5;
		var gridUV = abs(vec2(position.x % 1, position.y % 1) * 2.0 - 1.0);
		gridUV = invertLine ? gridUV : 1.0 - gridUV;
		var grid2 = smoothstep(drawWidth + lineAA, drawWidth - lineAA, gridUV);
		grid2 *= saturate(targetWidth / drawWidth);
		grid2 = mix(grid2, targetWidth, saturate(posDeriv * 2.0 - 1.0));
		grid2 = invertLine ? 1.0 - grid2 : grid2;
		return mix(grid2.x, 1.0, grid2.y);
	};
	function fragment() {
		pixelColor.rgb = color;
		pixelColor.a = 0;
		for (idx  in  0 ... 3) {
			var f = pow(10., float(idx));
			pixelColor.a = max(pixelColor.a, pristineGrid(transformedPosition.xy * (1 / (lineSpacing * f)), vec2(lineWidth * f, lineWidth * f) * (1 / (lineSpacing * f)), idx));
		};
	};
}

